name":"Homeowner Claim Appraisal","url":"https://alaskainsuranceappraiser.com/appraisal-practice/home-insurance-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial, HOA & Condo Appraisal","url":"https://alaskainsuranceappraiser.com/appraisal-practice/commercial-hoa-condo-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof, Hail & Ice Damage Appraisal","url":"https://alaskainsuranceappraiser.com/appraisal-practice/roof-damage-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Windstorm Damage Appraisal","url":"https://alaskainsuranceappraiser.com/appraisal-practice/windstorm-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Snow Load & Ice Dam Claims","url":"https://alaskainsuranceappraiser.com/appraisal-practice/snow-load-ice-dam-claims/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Frozen Pipe & Water Damage Appraisal","url":"https://alaskainsuranceappraiser.com/appraisal-practice/frozen-pipe-water-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire, Smoke & Wildfire Appraisal","url":"https://alaskainsuranceappraiser.com/appraisal-practice/fire-smoke-ash-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Earthquake Endorsement Claims","url":"https://alaskainsuranceappraiser.com/appraisal-practice/earthquake-endorsement-claims/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Remote & Off-Road-System Properties","url":"https://alaskainsuranceappraiser.com/appraisal-practice/remote-property-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Carrier Estimate Review","url":"https://alaskainsuranceappraiser.com/appraisal-practice/carrier-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Neutral Umpire Services","url":"https://alaskainsuranceappraiser.com/appraisal-practice/neutral-umpire-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Snow load damage","Earthquake claims","Remote construction costs"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}],"priceRange":"$$"},{"@type":"WebSite","@id":"https://alaskainsuranceappraiser.com/#website","url":"https://alaskainsuranceappraiser.com/","name":"Alaska Insurance Appraiser","publisher":{"@id":"https://alaskainsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://alaskainsuranceappraiser.com/alaska-appraisal-faq/#webpage","url":"https://alaskainsuranceappraiser.com/alaska-appraisal-faq/","name":"Alaska Insurance Appraisal FAQ | Costs, Timing, Rules","description":"Answers to common Alaska insurance appraisal questions: how it works, what it costs, how long it takes, earthquake and flood coverage and more.","inLanguage":"en-US","isPartOf":{"@id":"https://alaskainsuranceappraiser.com/#website"},"about":{"@id":"https://alaskainsuranceappraiser.com/#business"},"publisher":{"@id":"https://alaskainsuranceappraiser.com/#business"},"dateModified":"2026-11-13","primaryImageOfPage":{"@id":"https://alaskainsuranceappraiser.com/alaska-appraisal-faq/#primaryimage"},"breadcrumb":{"@id":"https://alaskainsuranceappraiser.com/alaska-appraisal-faq/#breadcrumb"},"mainEntity":{"@id":"https://alaskainsuranceappraiser.com/alaska-appraisal-faq/#faq"}},{"@type":"ImageObject","@id":"https://alaskainsuranceappraiser.com/alaska-appraisal-faq/#primaryimage","url":"https://alaskainsuranceappraiser.com/assets/img/photos/consultation-laptop.webp","contentUrl":"https://alaskainsuranceappraiser.com/assets/img/photos/consultation-laptop.webp","width":1200,"height":800,"caption":"Two colleagues reviewing figures on a laptop at an office table"},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://alaskainsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Appraisal FAQ","item":"https://alaskainsuranceappraiser.com/alaska-appraisal-faq/"}],"@id":"https://alaskainsuranceappraiser.com/alaska-appraisal-faq/#breadcrumb"},{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What is insurance appraisal?","acceptedAnswer":{"@type":"Answer","text":"A process in most property policies for resolving disagreements about the amount of a covered loss. Each side appoints an appraiser, the appraisers choose an umpire, and an award signed by two of the three sets the amount."}},{"@type":"Question","name":"Is appraisal the same as arbitration?","acceptedAnswer":{"@type":"Answer","text":"They are similar in that a neutral decides, but appraisal is usually limited to the amount of loss and tends to be less formal. Alaska courts and policy language determine how it works in a given case."}},{"@type":"Question","name":"Who can invoke appraisal?","acceptedAnswer":{"@type":"Answer","text":"Either the policyholder or the insurer, under the terms of the policy. A written demand is usually required."}},{"@type":"Question","name":"Does my Alaska policy have an appraisal clause?","acceptedAnswer":{"@type":"Answer","text":"Most homeowner, condo, landlord and commercial property policies do. Look in the conditions section for a paragraph titled Appraisal."}},{"@type":"Question","name":"How much does appraisal cost?","acceptedAnswer":{"@type":"Answer","text":"Each side pays its own appraiser, and the umpire's fee is usually split. Total cost depends on the size and complexity of the claim and, in Alaska, on travel to the property."}},{"@type":"Question","name":"How long does it take?","acceptedAnswer":{"@type":"Answer","text":"Often two to three months for a simple residential claim after appraisers are named. Larger, remote or umpire-heavy claims can take longer."}},{"@type":"Question","name":"When is the gap too small for appraisal?","acceptedAnswer":{"@type":"Answer","text":"If the costs would absorb most of the expected increase, a documented supplement request is often better. Our gap and fee estimator helps you check."}},{"@type":"Question","name":"Can I invoke appraisal after accepting a payment?","acceptedAnswer":{"@type":"Answer","text":"Often yes, depending on the policy and deadlines. Accepting a partial payment does not necessarily close a claim, but read any release carefully."}},{"@type":"Question","name":"Who regulates insurance in Alaska?","acceptedAnswer":{"@type":"Answer","text":"The Alaska Division of Insurance, part of the Department of Commerce, Community, and Economic Development. It handles consumer complaints and licenses insurers and adjusters."}},{"@type":"Question","name":"Does Alaska have a FAIR plan or a state wind pool?","acceptedAnswer":{"@type":"Answer","text":"No. Alaska does not operate a FAIR plan or a wind pool. Owners who cannot find standard coverage may turn to the surplus lines market."}},{"@type":"Question","name":"Does my homeowner policy cover earthquakes?","acceptedAnswer":{"@type":"Answer","text":"Usually not. Earthquake coverage is generally added by endorsement or separate policy and often carries a percentage deductible."}},{"@type":"Question","name":"Is flood covered?","acceptedAnswer":{"@type":"Answer","text":"Surface flooding, storm surge and glacial outburst flooding are typically excluded from homeowner policies and insured separately, for example through the National Flood Insurance Program."}},{"@type":"Question","name":"Can you work on properties off the road system?","acceptedAnswer":{"@type":"Answer","text":"Yes. Remote properties need travel planning, and repair estimates should account for freight, travel and seasonal access."}},{"@type":"Question","name":"Are you a public adjuster or a law firm?","acceptedAnswer":{"@type":"Answer","text":"No. We provide appraisal, estimating and umpire services. We do not negotiate claims outside appraisal and we do not give legal advice."}},{"@type":"Question","name":"Can you be my appraiser and the umpire?","acceptedAnswer":{"@type":"Answer","text":"No. We serve in one role per claim and disclose any prior involvement."}},{"@type":"Question","name":"What should I send for a free review?","acceptedAnswer":{"@type":"Answer","text":"Your declarations page, the carrier's full estimate, photos and any contractor estimates."}}],"@id":"https://alaskainsuranceappraiser.com/alaska-appraisal-faq/#faq"}]}</script>
</head>
